"use strict";

const fs = require("node:fs");
const path = require("node:path");
const { Readable } = require("node:stream");
const { fileURLToPath } = require("node:url");

const COMMENT_HEADER = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;

const BOOLEAN_OPTIONS = [
  "additionalProperties",
  "alphabetize",
  "arrayLength",
  "defaultNonNullable",
  "emptyObjectsUnknown",
  "enum",
  "enumValues",
  "conditionalEnums",
  "dedupeEnums",
  "excludeDeprecated",
  "exportType",
  "immutable",
  "rootTypes",
  "rootTypesNoSchemaPrefix",
  "rootTypesKeepCasing",
  "pathParamsAsTypes",
  "propertiesRequiredByDefault",
  "makePathsEnum",
  "generatePathParams",
  "readWriteMarkers",
];

const NODE_API_RULES = { "operation-operationId-unique": { severity: "error" } };
const ABORT = Symbol("spectype: fetch remote refs and retry");

let binding;
function engine(text, format, location, options, host) {
  binding ??= require("./native.cjs");
  // WebAssembly frees its copy of a Buffer only once the event loop turns, so sync loops would pile them up.
  if (Buffer.isBuffer(text) && binding.__napiBindingTarget !== "native") text = text.toString();
  const { code, warnings, error } = binding.generate(text, format, location, options, host);
  if (error) {
    const { message, ...details } = error;
    throw Object.assign(new Error(message), details);
  }
  return { code, warnings };
}

let tsModule;
function typescript(feature) {
  if (tsModule === undefined) {
    tsModule = null;
    // The project's own copy first: hooks build nodes with it, and its SyntaxKind numbers must match.
    for (const base of [process.cwd(), __dirname]) {
      try {
        const ts = require(require.resolve("typescript", { paths: [base] }));
        if (typeof ts.createPrinter === "function") {
          tsModule = ts;
          break;
        }
      } catch {}
    }
  }
  if (!tsModule && feature) throw new Error(`spectype: ${feature} needs the "typescript" package (5 or 6) installed`);
  return tsModule;
}

const colors = process.env.FORCE_COLOR !== "0";
const paint = (code, text) => (colors ? `\x1b[${code}m${text}\x1b[39m` : text);
const logError = (msg) => console.error(paint(31, ` ✘  ${msg}`));
const logWarn = (msg, silent) => silent || console.warn(paint(33, ` ⚠  ${msg}`));

/** What `openapiTS` resolves to: the generated statements, printed by {@link astToString}. */
class GeneratedSource {
  constructor(text) {
    this.text = text;
  }
}

function engineOptions(options, lint) {
  const out = { lint };
  for (const key of BOOLEAN_OPTIONS) if (options[key] !== undefined) out[key] = options[key];
  if (options.fix !== undefined) out.fix = options.fix;
  if (typeof options.inject === "string" && options.inject) out.inject = reprint(options.inject);
  return JSON.stringify(out);
}

/** openapi-typescript parses `inject` with `stringToAST` and prints it into an empty file. */
function reprint(source) {
  const ts = typescript();
  if (!ts) return source;
  const parsed = ts.createSourceFile("stringInput", source, ts.ScriptTarget.ESNext);
  const file = ts.createSourceFile("openapi-ts.ts", "", ts.ScriptTarget.ESNext, false, ts.ScriptKind.TS);
  file.statements = ts.factory.createNodeArray(parsed.statements);
  return ts.createPrinter({ newLine: ts.NewLineKind.LineFeed, removeComments: false }).printFile(file);
}

function redoclyRules(redocly) {
  const rules = redocly?.styleguide?.rules ?? redocly?.rules;
  if (!rules) return { oas3_0: NODE_API_RULES, oas3_1: NODE_API_RULES };
  return { oas3_0: rules.oas3_0 ?? {}, oas3_1: rules.oas3_1 ?? {} };
}

/** `resolve.http.headers` from a Redocly config, with `envVariable`s read now, as Redocly does per request. */
function httpHeaders(redocly) {
  const headers = redocly?.resolve?.http?.headers;
  if (!Array.isArray(headers) || !headers.length) return undefined;
  const resolved = headers.map((h) =>
    h?.envVariable !== undefined ? { ...h, envVariable: undefined, value: process.env[h.envVariable] || "" } : h,
  );
  return JSON.stringify(resolved);
}

/** Redocly's `BaseResolver.loadExternalRef`. */
async function fetchDocument(url, headers) {
  binding ??= require("./native.cjs");
  const response = await fetch(url, headers ? { headers: binding.requestHeaders(url, headers) } : undefined);
  if (!response.ok) throw new Error(`Failed to load ${url}: ${response.status} ${response.statusText}`);
  return { text: await response.text(), mimeType: response.headers.get("content-type") ?? undefined };
}

async function readSource(source, cwd, headers) {
  let location = fileURLToPath(cwd);
  if (typeof source === "string" && /^(https?|file):\/\//.test(source)) source = new URL(source);
  if (source instanceof URL) {
    if (source.protocol === "file:") {
      location = fileURLToPath(source);
      return { text: fs.readFileSync(location), format: "yaml", location };
    }
    return { text: (await fetchDocument(source.href, headers)).text, format: "yaml", location: source.href };
  }
  if (source instanceof Readable) {
    let text = "";
    source.setEncoding("utf8");
    for await (const chunk of source) text += chunk;
    return { text: text.trim(), format: "auto", location };
  }
  if (Buffer.isBuffer(source)) return { text: source, format: "auto", location };
  if (typeof source === "string") return { text: source, format: "auto", location };
  if (typeof source === "object" && !Array.isArray(source)) {
    return { text: JSON.stringify(source), format: "json", location };
  }
  throw new Error(`Expected string, object, or Buffer. Got ${Array.isArray(source) ? "Array" : typeof source}`);
}

/** `parseRef` + `resolveRef` from openapi-typescript, over the bundled document. */
function resolveRef(document, $ref, silent, visited = []) {
  const pointer = ($ref.split("#/")[1] ?? "")
    .split("/")
    .filter(Boolean)
    .map((s) => decodeURIComponent(s.replace(/~1/g, "/").replace(/~0/g, "~")));
  if (!pointer.length) return undefined;
  let node = document;
  for (const key of pointer) {
    if (node && typeof node === "object" && node[key]) {
      node = node[key];
    } else {
      logWarn(`Could not resolve $ref "${$ref}"`, silent);
      return undefined;
    }
  }
  if (node && typeof node === "object" && node.$ref) {
    if (visited.includes(node.$ref)) {
      logWarn(`Could not resolve circular $ref "${$ref}"`, silent);
      return undefined;
    }
    return resolveRef(document, node.$ref, silent, [...visited, node.$ref]);
  }
  return node;
}

const TYPE_KINDS = {
  AnyKeyword: "keyword",
  BigIntKeyword: "keyword",
  BooleanKeyword: "keyword",
  IntrinsicKeyword: "keyword",
  NeverKeyword: "keyword",
  NumberKeyword: "keyword",
  ObjectKeyword: "keyword",
  StringKeyword: "keyword",
  SymbolKeyword: "keyword",
  UndefinedKeyword: "keyword",
  UnknownKeyword: "keyword",
  VoidKeyword: "keyword",
  UnionType: "union",
  IntersectionType: "intersection",
  FunctionType: "function",
  ConstructorType: "function",
  ConditionalType: "function",
  TypeOperator: "typeOperator",
  TypeQuery: "query",
  InferType: "query",
  ArrayType: "array",
  TupleType: "tuple",
};

let tools;
function tsTools(feature) {
  if (tools) return tools;
  const ts = typescript(feature);
  const K = ts.SyntaxKind;
  return (tools = {
    ts,
    K,
    f: ts.factory,
    kinds: new Map(Object.entries(TYPE_KINDS).map(([name, kind]) => [K[name], kind])),
    printer: ts.createPrinter({ newLine: ts.NewLineKind.LineFeed, removeComments: false }),
    emptyFile: ts.createSourceFile("openapi-ts.ts", "", ts.ScriptTarget.ESNext, false, ts.ScriptKind.TS),
  });
}

/**
 * The engine's host for one `openapiTS` call: remote documents from `remote`
 * (a miss is recorded in `missing` for the caller to fetch and retry), and the user's hooks,
 * which get real TypeScript nodes.
 */
function createHost(options, remote, missing) {
  const state = { thrown: undefined, document: undefined, nodes: [] };
  const host = {
    load(url) {
      if (remote.has(url)) return remote.get(url);
      missing.add(url);
      return null;
    },
  };
  const hooks = ["transform", "postTransform", "transformProperty"].filter((h) => typeof options[h] === "function");
  if (!hooks.length) return { host, state };

  const silent = options.silent ?? false;
  const ctx = {
    ...Object.fromEntries(BOOLEAN_OPTIONS.map((k) => [k, options[k] ?? k === "defaultNonNullable"])),
    discriminators: { objects: {}, refsHandled: [] },
    injectFooter: [],
    inject: options.inject ?? undefined,
    redoc: options.redocly,
    silent,
    transform: options.transform,
    postTransform: options.postTransform,
    transformProperty: options.transformProperty,
    resolve: ($ref) => resolveRef(state.document, $ref, silent),
  };
  const value = (v) => (v == null ? undefined : typeof v === "number" ? state.nodes[v] : JSON.parse(v));
  const feature = `the ${hooks[0]} option`;
  const print = (node, file) => {
    const { ts, printer, emptyFile, kinds, K } = tsTools(feature);
    const kind =
      node.kind === K.LiteralType && node.literal.kind === K.NullKeyword ? "keyword" : (kinds.get(node.kind) ?? "other");
    return { text: printer.printNode(ts.EmitHint.Unspecified, node, file ?? emptyFile), kind };
  };
  const parseType = (text) => {
    const { ts } = tsTools(feature);
    const file = ts.createSourceFile("spectype.ts", `type __T = ${text};`, ts.ScriptTarget.ESNext, true, ts.ScriptKind.TS);
    return { type: file.statements[0].type, file };
  };
  const run = (fn) => {
    if (missing.size) throw ABORT;
    try {
      return fn();
    } catch (error) {
      state.thrown = { error };
      throw error;
    }
  };

  host.document = (json, discriminators) => {
    state.document = JSON.parse(json);
    ctx.discriminators = JSON.parse(discriminators);
    const walk = (v) => {
      state.nodes.push(v);
      for (const c of Array.isArray(v) ? v : Object.values(v)) if (c !== null && typeof c === "object") walk(c);
    };
    walk(state.document);
  };
  if (options.transform) {
    host.transform = (schema, path, component) =>
      run(() => {
        const result = options.transform(value(schema), { path, schema: value(component), ctx });
        if (!result) return undefined;
        if ("schema" in result) return { ...print(result.schema), questionToken: Boolean(result.questionToken) };
        return print(result);
      });
  }
  if (options.postTransform) {
    host.postTransform = (text, path, component) =>
      run(() => {
        const { type, file } = parseType(text);
        const result = options.postTransform(type, { path, schema: value(component), ctx });
        return !result || result === type ? undefined : print(result, file);
      });
  }
  if (options.transformProperty) {
    host.transformProperty = (input, schema, path, component) =>
      run(() => {
        const { ts, f, K, printer } = tsTools(feature);
        const { type, file } = parseType(input.type);
        const name =
          input.nameKind === "identifier"
            ? f.createIdentifier(input.name)
            : input.nameKind === "string"
              ? f.createStringLiteral(input.name)
              : f.createNumericLiteral(input.name);
        const property = f.createPropertySignature(
          input.readonly ? [f.createModifier(K.ReadonlyKeyword)] : [],
          name,
          input.optional ? f.createToken(K.QuestionToken) : undefined,
          type,
        );
        const result = options.transformProperty(property, value(schema), { path, schema: value(component), ctx });
        if (!result) return null;
        const untouched =
          result === property && !ts.getSyntheticLeadingComments(result) && !ts.getSyntheticTrailingComments(result);
        if (untouched) return null;
        if (input.jsdoc != null) {
          ts.addSyntheticLeadingComment(result, K.MultiLineCommentTrivia, input.jsdoc, true);
        }
        return printer.printNode(ts.EmitHint.Unspecified, result, file);
      });
  }
  return { host, state };
}

function report(error, silent) {
  for (const pointer of error.pointers ?? []) logError(`Can't resolve $ref at ${pointer}`);
  for (const problem of error.problems ?? []) {
    if (problem.error) logError(problem.message);
    else logWarn(problem.message, silent);
  }
}

/**
 * Convert an OpenAPI 3.x document to TypeScript, like openapi-typescript's `openapiTS`.
 * Resolves to statements for {@link astToString}.
 */
async function openapiTS(source, options = {}) {
  if (!source) throw new Error("Empty schema. Please specify a URL, file path, or Redocly Config");
  const cwd = options.cwd instanceof URL ? options.cwd : new URL(`file://${options.cwd ?? process.cwd()}/`);
  const headers = httpHeaders(options.redocly);
  const { text, format, location } = await readSource(source, cwd, headers);
  const silent = options.silent ?? false;
  const json = engineOptions(options, redoclyRules(options.redocly));
  const remote = new Map();
  const missing = new Set();
  for (;;) {
    missing.clear();
    const { host, state } = createHost(options, remote, missing);
    let result;
    let failure;
    try {
      result = engine(text, format, location, json, host);
    } catch (error) {
      failure = error;
    }
    if (missing.size) {
      await Promise.all(
        [...missing].map(async (url) => remote.set(url, await fetchDocument(url, headers).catch(() => null))),
      );
      continue;
    }
    if (state.thrown) throw state.thrown.error;
    if (failure) {
      report(failure, silent);
      throw failure;
    }
    for (const warning of result.warnings) logWarn(warning, silent);
    return [new GeneratedSource(result.code.slice(COMMENT_HEADER.length))];
  }
}

/** Print what {@link openapiTS} returned, optionally mixed with TypeScript nodes, like openapi-typescript. */
function astToString(ast, options) {
  const nodes = Array.isArray(ast) ? ast : [ast];
  if (!options?.formatOptions && nodes.every((n) => n instanceof GeneratedSource)) {
    return nodes.map((n) => n.text).join("");
  }
  const ts = typescript("astToString with TypeScript nodes");
  const file = ts.createSourceFile(
    options?.fileName ?? "openapi-ts.ts",
    options?.sourceText ?? "",
    ts.ScriptTarget.ESNext,
    false,
    ts.ScriptKind.TS,
  );
  file.statements = ts.factory.createNodeArray(
    nodes.map((n) => (n instanceof GeneratedSource ? ts.factory.createIdentifier(n.text.replace(/\n$/, "")) : n)),
  );
  const printer = ts.createPrinter({
    newLine: ts.NewLineKind.LineFeed,
    removeComments: false,
    ...options?.formatOptions,
  });
  return printer.printFile(file);
}

function generateSync(text, format, location, options = {}) {
  return engine(text, format, location, engineOptions(options, {}), { load: () => null }).code;
}

/** Generate TypeScript (with the comment header) from YAML/JSON text or a parsed document. */
function generate(spec, options) {
  const text = typeof spec === "string" ? spec : JSON.stringify(spec);
  return generateSync(text, typeof spec === "string" ? "auto" : "json", `${process.cwd()}/`, options);
}

/** Generate TypeScript (with the comment header) from a file; relative `$ref`s resolve against it. */
function generateFile(file, options) {
  const location = path.resolve(file);
  let text;
  try {
    text = fs.readFileSync(location);
  } catch (error) {
    throw new Error(`Could not read ${location}: ${error.message}`);
  }
  return generateSync(text, "yaml", location, options);
}

exports.default = openapiTS;
exports.openapiTS = openapiTS;
exports.astToString = astToString;
exports.COMMENT_HEADER = COMMENT_HEADER;
exports.generate = generate;
exports.generateFile = generateFile;
